// E-4: the C# port of src/shared/history.ts against contracts/golden/history.json, plus the desktop additions (extra channels, gaps, sampler,
// segment restart, markers, hover index). The golden is generated by the web's own functions (tools/contracts/golden_history.ts).
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using NUnit.Framework;

namespace WebGL.Telemetry.Tests
{
    using JObj = Dictionary<string, object>;

    public class AnalysisHistoryTests
    {
        static readonly Channel[] Web = { Channel.Altitude, Channel.Speed, Channel.Voltage, Channel.Throttle, Channel.Vibration };
        static readonly string[] WebIds = { "altitude", "speed", "voltage", "throttle", "vibration" };

        /// <summary>A frame with only the fields history.ts reads (the golden stores those).</summary>
        static TelemetryFrame F(JObj f)
        {
            return new TelemetryFrame
            {
                p = C.V(f, "p"), v = C.V(f, "v"), u = C.V(f, "u"),
                bat = new BatteryState { v = C.N(C.O(f, "bat"), "v") },
                vib = C.N(f, "vib"),
            };
        }

        static Series Make(IEnumerable<double> values, int capacity)
        {
            var s = new Series(capacity);
            foreach (double v in values) s.Add(v);
            return s;
        }

        /// <summary>Parses "M12.3 4.5L..." into pairs.</summary>
        static List<double[]> ParsePath(string d)
        {
            var r = new List<double[]>();
            if (string.IsNullOrEmpty(d)) return r;
            foreach (string seg in d.Split(new[] { 'M', 'L' }, StringSplitOptions.RemoveEmptyEntries))
            {
                string[] xy = seg.Split(' ');
                r.Add(new[] { double.Parse(xy[0], CultureInfo.InvariantCulture), double.Parse(xy[1], CultureInfo.InvariantCulture) });
            }
            return r;
        }

        [Test]
        public void Constants_AndSeriesOrder_MatchTheWeb()
        {
            var g = C.Golden("history");
            Assert.AreEqual(C.I(g, "sample_hz"), HistoryConstants.SampleHz);
            Assert.AreEqual(C.I(g, "length"), HistoryConstants.Length);
            CollectionAssert.AreEqual(C.A(g, "series").Cast<string>().ToArray(), WebIds);
            for (int i = 0; i < Web.Length; i++) Assert.AreEqual(i, (int)Web[i], "the first five channels are the web's SERIES in order");
            Assert.AreEqual(5, History.WebSeriesCount);
            Assert.AreEqual(Enum.GetValues(typeof(Channel)).Length, History.ChannelCount);
            Assert.AreEqual(60.0, HistoryConstants.WindowS, 0.3, "60 s window");
        }

        [Test]
        public void SeriesValue_Golden()
        {
            var g = C.Golden("history");
            var cs = new Cases("history.series_value", C.N(g, "tolerance"));
            foreach (JObj c in C.A(g, "series_value"))
            {
                cs.Case();
                TelemetryFrame f = F(C.O(c, "frame"));
                JObj o = C.O(c, "out");
                for (int i = 0; i < Web.Length; i++) cs.Near(C.N(o, WebIds[i]), History.ChannelValue(Web[i], f), WebIds[i]);
            }
            cs.Done();
        }

        [Test]
        public void PushHistory_Golden_ShortRing()
        {
            var g = C.Golden("history");
            var ph = C.O(g, "push_history");
            int length = C.I(ph, "length");
            var frames = C.A(ph, "frames").Cast<JObj>().Select(F).ToList();
            var cs = new Cases("history.push_history", C.N(g, "tolerance"));
            var h = new FlightHistory(length);
            int pushed = 0;
            foreach (JObj step in C.A(ph, "steps"))
            {
                while (pushed < C.I(step, "n")) h.Push(frames[pushed++]);
                cs.Case();
                JObj exp = C.O(step, "history");
                for (int i = 0; i < Web.Length; i++)
                {
                    double[] e = C.V(exp, WebIds[i]);
                    Series s = h[Web[i]];
                    cs.Eq(e.Length, s.Count, WebIds[i] + " length after " + pushed);
                    for (int k = 0; k < e.Length && k < s.Count; k++) cs.Near(e[k], s[k], WebIds[i] + "[" + k + "] after " + pushed);
                }
            }
            cs.Done();
        }

        [Test]
        public void PushHistory_Golden_FullWindow()
        {
            var g = C.Golden("history");
            var fw = C.O(g, "full_window");
            var cs = new Cases("history.full_window", C.N(g, "tolerance"));
            var h = new FlightHistory();
            for (int i = 0; i < C.I(fw, "pushes"); i++)
            {
                h.Push(new TelemetryFrame
                {
                    p = new[] { 0, 0, -(10 + 8 * Math.Sin(i / 17.0)) },
                    v = new[] { 3 * Math.Cos(i / 9.0), 2 * Math.Sin(i / 11.0), 0.5 * Math.Sin(i / 5.0) },
                    u = new[] { 0.5 + 0.2 * Math.Sin(i / 7.0), 0.5, 0.5, 0.5 },
                    bat = new BatteryState { v = 16 - i * 0.004, i = 10, rem = 1 - i / 1000.0 },
                    vib = 3 + Math.Sin(i / 3.0),
                });
            }
            Assert.AreEqual(250, (int)h.TotalSamples);
            for (int i = 0; i < Web.Length; i++)
            {
                cs.Case();
                Series s = h[Web[i]];
                string id = WebIds[i];
                cs.Eq(C.I(C.O(fw, "length"), id), s.Count, id + " length");
                cs.Near(C.N(C.O(fw, "first"), id), s[0], id + " first");
                cs.Near(C.N(C.O(fw, "last"), id), s[s.Count - 1], id + " last");
                double sum = 0;
                for (int k = 0; k < s.Count; k++) sum += s[k];
                cs.Near(C.N(C.O(fw, "sum"), id), sum, id + " sum", 1e-4);
            }
            cs.Done();
        }

        [Test]
        public void Sparkline_Golden_HandMade()
        {
            var g = C.Golden("history");
            var cs = new Cases("history.sparkline", C.N(g, "tolerance"));
            foreach (JObj c in C.A(g, "sparkline"))
            {
                cs.Case();
                string name = C.S(c, "name");
                double w = C.N(c, "width"), h = C.N(c, "height");
                var values = C.A(c, "values").Select(x => (double)x).ToArray();
                Series s = Make(values, C.I(c, "capacity"));
                JObj o = C.O(c, "out");
                double minSpan = C.N(c, "minSpan");
                SparkRange r = Sparkline.Range(s, minSpan);
                if (values.Length == 0)
                {
                    cs.Eq(true, double.IsNaN(s.Last), name + " last of empty is NaN");
                    cs.True(C.IsNull(o, "last"), name + " golden last of empty is null");
                    cs.Eq(string.Empty, Sparkline.Path(s, w, h, minSpan), name + " path of empty");
                    continue;
                }
                cs.Near(C.N(o, "min"), r.Min, name + " min");
                cs.Near(C.N(o, "max"), r.Max, name + " max");
                cs.Near(C.N(o, "last"), s.Last, name + " last");
                CheckPath(cs, name, C.S(o, "d"), s, w, h, minSpan);
            }
            cs.Done();
        }

        static void CheckPath(Cases cs, string name, string expected, Series s, double w, double h, double minSpan)
        {
            string actual = Sparkline.Path(s, w, h, minSpan);
            List<double[]> e = ParsePath(expected), a = ParsePath(actual);
            cs.Eq(e.Count, a.Count, name + " points");
            // one decimal in both: the same rounding gives equal strings, a half-step tie may differ by 0.1
            for (int i = 0; i < e.Count && i < a.Count; i++)
            {
                cs.Near(e[i][0], a[i][0], name + " x" + i, 0.1001);
                cs.Near(e[i][1], a[i][1], name + " y" + i, 0.1001);
            }
            cs.True(s.Count < 2 || (expected.StartsWith("M") && actual.StartsWith("M")), name + " starts with M");
        }

        [Test]
        public void RealFlight_Golden_PushAndSparkline()
        {
            string path = GoldenReplayTests.FindFlightTwf();
            if (path == null) Assert.Inconclusive("x500v2_flight.twf not found");
            var g = C.Golden("history");
            var rf = C.O(g, "real_flight");
            var sch = new ReplaySchedule(TwfFile.Decode(File.ReadAllBytes(path)));
            var h = new FlightHistory();
            int start = C.I(rf, "start_g"), step = C.I(rf, "step_g"), count = C.I(rf, "count");
            for (int i = 0; i < count; i++) h.Push(sch.Frame(start + i * step));
            var chart = C.O(g, "chart");
            var spans = C.O(chart, "minSpan");
            double w = C.N(chart, "width"), ht = C.N(chart, "height");
            var cs = new Cases("history.real_flight", 1e-5);
            for (int i = 0; i < Web.Length; i++)
            {
                string id = WebIds[i];
                var e = C.O(C.O(rf, "series"), id);
                Series s = h[Web[i]];
                cs.Case();
                cs.Eq(C.I(C.O(rf, "length"), id), s.Count, id + " length");
                cs.Near(C.N(e, "first"), s[0], id + " first");
                cs.Near(C.N(e, "last"), s[s.Count - 1], id + " last");
                double sum = 0;
                for (int k = 0; k < s.Count; k++) sum += s[k];
                cs.Near(C.N(e, "sum"), sum, id + " sum", 1e-3);
                var sp = C.O(e, "spark");
                SparkRange r = Sparkline.Range(s, C.N(spans, id));
                cs.Near(C.N(sp, "min"), r.Min, id + " spark min");
                cs.Near(C.N(sp, "max"), r.Max, id + " spark max");
                cs.Near(C.N(sp, "last"), s.Last, id + " spark last");
                CheckPath(cs, id, C.S(sp, "d"), s, w, ht, C.N(spans, id));
            }
            cs.Done();
        }

        // ───────────────────────── desktop additions ─────────────────────────

        [Test]
        public void ExtraChannels_Values()
        {
            var f = new TelemetryFrame
            {
                p = new[] { 0, 0, -13.5 }, v = new[] { 3.0, 4.0, -1.5 }, u = new[] { 0.2, 0.4, 0.6, 0.8 },
                bat = new BatteryState { v = 14.21, i = 18.7, rem = 0.44 }, rpm = new[] { 9397.0, 8467.0, 0.0, 8993.0 }, vib = 5.8,
            };
            Assert.AreEqual(5.0, History.ChannelValue(Channel.HSpeed, f), 1e-12);
            Assert.AreEqual(1.5, History.ChannelValue(Channel.VSpeed, f), 1e-12, "climb positive (NED down negated)");
            Assert.AreEqual(44.0, History.ChannelValue(Channel.BatteryPct, f), 1e-9);
            Assert.AreEqual(9397.0, History.ChannelValue(Channel.Rpm1, f));
            Assert.AreEqual(0.0, History.ChannelValue(Channel.Rpm3, f));
            Assert.AreEqual(8993.0, History.ChannelValue(Channel.Rpm4, f));
            Assert.AreEqual(Math.Sqrt(25 + 2.25), History.ChannelValue(Channel.Speed, f), 1e-12);
        }

        [Test]
        public void Series_RingDropsTheOldest()
        {
            var s = new Series(3);
            for (int i = 1; i <= 5; i++) s.Add(i);
            Assert.AreEqual(3, s.Count);
            Assert.AreEqual(3, s[0]); Assert.AreEqual(4, s[1]); Assert.AreEqual(5, s[2]);
            Assert.AreEqual(5, s.Last);
            Assert.Throws<ArgumentOutOfRangeException>(() => { var _ = s[3]; });
            s.Clear();
            Assert.AreEqual(0, s.Count);
            Assert.IsTrue(double.IsNaN(s.Last));
        }

        [Test]
        public void Range_IgnoresGaps_AndWidensToMinSpan()
        {
            var s = Make(new[] { 5.0, 5.1, double.NaN, 4.9, 5.0 }, 10);
            SparkRange r = Sparkline.Range(s, 2);
            Assert.AreEqual(4.9, r.Min, 1e-12);
            Assert.AreEqual(5.1, r.Max, 1e-12);
            Assert.AreEqual(2.0, r.Span, 1e-12, "flat signal widened to minSpan");
            Assert.AreEqual(5.0 - 1.0, r.Lo, 1e-12, "centred on the middle of the data");
            Assert.IsTrue(r.Drawable);
            Assert.AreEqual(4, r.Samples);

            var onlyGaps = Make(new[] { double.NaN, double.NaN }, 10);
            SparkRange g = Sparkline.Range(onlyGaps, 2);
            Assert.IsFalse(g.Drawable);
            Assert.AreEqual(0, g.Samples);

            // isolated samples between gaps draw no segment
            var isolated = Make(new[] { 1.0, double.NaN, 2.0 }, 10);
            Assert.IsFalse(Sparkline.Range(isolated, 1).Drawable);
        }

        [Test]
        public void Range_OfSeveralLines_IsShared()
        {
            var a = Make(new[] { 3.0, 3.5 }, 10);
            var b = Make(new[] { -1.0, 0.5 }, 10);
            SparkRange r = Sparkline.Range(new[] { a, b }, 2, 1);
            Assert.AreEqual(-1.0, r.Min); Assert.AreEqual(3.5, r.Max);
            Assert.AreEqual(4.5, r.Span, 1e-12);
        }

        [Test]
        public void IndexAt_MapsX_AndRejectsOutside()
        {
            const double w = 120; const int cap = 240;
            // 3 samples: the newest at x = width
            Assert.AreEqual(2, Sparkline.IndexAt(w, 3, w, cap));
            Assert.AreEqual(1, Sparkline.IndexAt(w - Sparkline.Step(w, cap), 3, w, cap));
            Assert.AreEqual(0, Sparkline.IndexAt(w - 2 * Sparkline.Step(w, cap) + 0.1, 3, w, cap));
            Assert.AreEqual(-1, Sparkline.IndexAt(10, 3, w, cap), "left of the data");
            Assert.AreEqual(-1, Sparkline.IndexAt(w, 0, w, cap), "no samples");
            Assert.AreEqual(239, Sparkline.IndexAt(w, 240, w, cap));
            Assert.AreEqual(0, Sparkline.IndexAt(0, 240, w, cap));
        }

        static TelemetryFrame Frame(int seg, double alt = 5)
        {
            return new TelemetryFrame { seg = seg, p = new[] { 0, 0, -alt }, v = new double[3], u = new[] { 0.5, 0.5, 0.5, 0.5 }, rpm = new double[4], bat = new BatteryState { v = 15, rem = 0.5 } };
        }

        [Test]
        public void Recorder_SamplesAtFourHz_NotPerFrame()
        {
            var rec = new AnalysisRecorder();
            var f = Frame(0);
            int added = 0;
            // 5 s of rendered frames at 60 Hz
            for (int i = 0; i < 300; i++) if (rec.Update(10 + i / 60.0, f, true)) added++;
            Assert.AreEqual(20, added, 1, "4 Hz over 5 s");
            Assert.AreEqual(added, rec.History.Count);
            Assert.AreEqual(added, (int)rec.History.TotalSamples);
        }

        [Test]
        public void Recorder_NoFrame_AddsNothing_AndKeepsTheClockWaiting()
        {
            var rec = new AnalysisRecorder();
            Assert.IsFalse(rec.Update(1, null, true));
            Assert.AreEqual(0, rec.History.Count);
            Assert.IsTrue(rec.Update(2, Frame(0), true), "the first frame is sampled at once");
        }

        [Test]
        public void Recorder_StaleLink_RecordsGaps()
        {
            var rec = new AnalysisRecorder();
            var f = Frame(0, 7);
            rec.Update(0, f, true);
            rec.Update(0.25, f, true);
            rec.Update(0.5, f, false);
            rec.Update(0.75, f, false);
            Series alt = rec.History[Channel.Altitude];
            Assert.AreEqual(4, alt.Count);
            Assert.AreEqual(7, alt[1]);
            Assert.IsTrue(double.IsNaN(alt[2]) && double.IsNaN(alt[3]), "no flat line over a stall");
            Assert.IsTrue(double.IsNaN(rec.History[Channel.Rpm1][3]));
        }

        [Test]
        public void Recorder_SegmentChange_RestartsTheChartsAndMarkers()
        {
            var rec = new AnalysisRecorder();
            for (int i = 0; i < 8; i++) rec.Update(i * 0.25, Frame(0), true);
            rec.AddAlert("motor1:rpm", AlertSeverity.Critical, "x");
            Assert.AreEqual(8, rec.History.Count);
            Assert.AreEqual(1, rec.Markers.Count);
            Assert.IsTrue(rec.Update(2.0, Frame(1), true));
            Assert.AreEqual(1, rec.History.Count, "a replay loop wrap is a discontinuity: start again");
            Assert.AreEqual(0, rec.Markers.Count);
        }

        [Test]
        public void Recorder_LongHitch_DoesNotBurst()
        {
            var rec = new AnalysisRecorder();
            var f = Frame(0);
            rec.Update(0, f, true);
            Assert.IsTrue(rec.Update(30, f, true), "one sample after a 30 s hitch");
            Assert.IsFalse(rec.Update(30.01, f, true), "and not a catch-up burst");
            Assert.AreEqual(2, rec.History.Count);
        }

        [Test]
        public void Markers_AnchorToSamples_AndScrollWithTheChart()
        {
            var rec = new AnalysisRecorder();
            rec.Update(0, Frame(0), true);
            rec.Update(0.25, Frame(0), true);
            rec.AddAlert("battery:low", AlertSeverity.Warning, "Batería baja");
            Assert.AreEqual(1, rec.Markers[0].Sample, "the newest sample");
            rec.AddFault("motor_failure:3", 30, "Falla");
            Assert.AreEqual(120, rec.Markers[1].Span, "30 s at 4 Hz");
            // 4 more samples: the alert is now 4 samples older
            for (int i = 0; i < 4; i++) rec.Update(0.5 + i * 0.25, Frame(0), true);
            long newest = rec.History.TotalSamples - 1;
            Assert.AreEqual(4, (int)(newest - rec.Markers[0].Sample));
        }

        [Test]
        public void MarkerLog_KeepsTheLastOnes()
        {
            var log = new MarkerLog(3);
            for (int i = 0; i < 5; i++) log.Add(new Marker { Sample = i });
            Assert.AreEqual(3, log.Count);
            Assert.AreEqual(2, log[0].Sample); Assert.AreEqual(4, log[2].Sample);
        }

        [Test]
        public void ChartSpecs_AreTheWebOnesPlusTheDesktopAdditions()
        {
            var ids = ChartSpec.All.Select(c => c.Id).ToArray();
            CollectionAssert.AreEqual(new[] { "altitude", "speed", "voltage", "level", "throttle", "rpm", "vibration" }, ids);
            var g = C.Golden("history");
            var spans = C.O(C.O(g, "chart"), "minSpan");
            foreach (var c in ChartSpec.All)
                if (spans.ContainsKey(c.Id)) Assert.AreEqual(C.N(spans, c.Id), c.MinSpan, c.Id + ": minSpan of FlightUI.tsx CHARTS");
            foreach (var c in ChartSpec.All)
            {
                Assert.IsNotNull(TelemetryStrings.T(c.TitleKey, "es"));
                Assert.IsNotNull(TelemetryStrings.T(c.TitleKey, "en"));
                if (c.LineKeys != null)
                {
                    Assert.AreEqual(c.Lines.Length, c.LineKeys.Length);
                    foreach (string k in c.LineKeys) { TelemetryStrings.T(k, "es"); TelemetryStrings.T(k, "en"); }
                }
            }
            Assert.AreEqual(4, ChartSpec.All.First(c => c.Id == "rpm").Lines.Length, "4 motors");
        }
    }
}
